import java.util.*;
import java.util.function.LongSupplier;

public class Solution {
    interface RateLimiter {
        boolean allow(String clienteId);
    }

    // O(1) de tempo e O(1) de memória por cliente: dois números por balde.
    static class TokenBucket implements RateLimiter {
        private static final class Balde {
            double tokens;
            long ultimaRecarga;

            Balde(double tokens, long ultimaRecarga) {
                this.tokens = tokens;
                this.ultimaRecarga = ultimaRecarga;
            }
        }

        private final int capacidade;
        private final double recargaPorSegundo;
        private final LongSupplier relogio;
        private final Map<String, Balde> baldes = new HashMap<>();

        TokenBucket(int capacidade, double recargaPorSegundo, LongSupplier relogio) {
            if (capacidade < 1) throw new IllegalArgumentException("capacidade deve ser >= 1");
            if (!(recargaPorSegundo > 0)) throw new IllegalArgumentException("recarga deve ser positiva");
            this.capacidade = capacidade;
            this.recargaPorSegundo = recargaPorSegundo;
            this.relogio = Objects.requireNonNull(relogio);
        }

        @Override
        public synchronized boolean allow(String clienteId) {
            long agora = relogio.getAsLong();
            Balde b = baldes.computeIfAbsent(clienteId, id -> new Balde(capacidade, agora));
            long decorrido = Math.max(0, agora - b.ultimaRecarga); // relógio voltando não gera tokens
            // multiplica antes de dividir: 500 ms * 2/s / 1000 = 1.0 exato
            b.tokens = Math.min(capacidade, b.tokens + decorrido * recargaPorSegundo / 1000.0);
            b.ultimaRecarga = Math.max(b.ultimaRecarga, agora);
            if (b.tokens >= 1) {
                b.tokens -= 1;
                return true;
            }
            return false;
        }
    }

    // O(1) amortizado por chamada; memória O(limite) por cliente.
    static class SlidingWindowLog implements RateLimiter {
        private final int limite;
        private final long janelaMillis;
        private final LongSupplier relogio;
        private final Map<String, ArrayDeque<Long>> logs = new HashMap<>();

        SlidingWindowLog(int limite, long janelaMillis, LongSupplier relogio) {
            if (limite < 1) throw new IllegalArgumentException("limite deve ser >= 1");
            if (janelaMillis < 1) throw new IllegalArgumentException("janela deve ser >= 1");
            this.limite = limite;
            this.janelaMillis = janelaMillis;
            this.relogio = Objects.requireNonNull(relogio);
        }

        @Override
        public synchronized boolean allow(String clienteId) {
            long agora = relogio.getAsLong();
            ArrayDeque<Long> log = logs.computeIfAbsent(clienteId, id -> new ArrayDeque<>());
            while (!log.isEmpty() && log.peekFirst() <= agora - janelaMillis) log.pollFirst();
            if (log.size() >= limite) return false;
            log.addLast(agora);
            return true;
        }
    }
}

