import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import java.time.Duration;

class SolutionTest {
    final long[] agora = {0};

    @Test void bucketComecaCheioEEsvazia() {
        Solution.RateLimiter rl = new Solution.TokenBucket(3, 1, () -> agora[0]);
        assertTrue(rl.allow("a"));
        assertTrue(rl.allow("a"));
        assertTrue(rl.allow("a"));
        assertFalse(rl.allow("a"));
    }

    @Test void bucketRecargaProporcional() {
        var rl = new Solution.TokenBucket(2, 2, () -> agora[0]);
        assertTrue(rl.allow("a"));
        assertTrue(rl.allow("a"));
        assertFalse(rl.allow("a"));
        agora[0] = 499;
        assertFalse(rl.allow("a"));
        agora[0] = 500;
        assertTrue(rl.allow("a"));
        assertFalse(rl.allow("a"));
    }

    @Test void bucketNaoPassaDaCapacidade() {
        var rl = new Solution.TokenBucket(2, 10, () -> agora[0]);
        rl.allow("a");
        agora[0] = 3_600_000;
        assertTrue(rl.allow("a"));
        assertTrue(rl.allow("a"));
        assertFalse(rl.allow("a"));
    }

    @Test void bucketRelogioVoltandoNaoGeraTokens() {
        var rl = new Solution.TokenBucket(1, 1, () -> agora[0]);
        agora[0] = 10_000;
        assertTrue(rl.allow("a"));
        agora[0] = 5_000;
        assertFalse(rl.allow("a"));
        agora[0] = 10_500;
        assertFalse(rl.allow("a")); // meio token
        agora[0] = 11_000;
        assertTrue(rl.allow("a"));
    }

    @Test void bucketClientesIndependentes() {
        var rl = new Solution.TokenBucket(1, 1, () -> agora[0]);
        assertTrue(rl.allow("a"));
        assertFalse(rl.allow("a"));
        assertTrue(rl.allow("b"));
    }

    @Test void logJanelaDeslizante() {
        Solution.RateLimiter rl = new Solution.SlidingWindowLog(3, 1_000, () -> agora[0]);
        for (long t : new long[] {0, 1, 2}) {
            agora[0] = t;
            assertTrue(rl.allow("a"), "t=" + t);
        }
        agora[0] = 3;
        assertFalse(rl.allow("a"));
        agora[0] = 999;
        assertFalse(rl.allow("a"));
        agora[0] = 1_000;
        assertTrue(rl.allow("a"));
        assertFalse(rl.allow("a"));
        agora[0] = 1_001;
        assertTrue(rl.allow("a"));
    }

    @Test void logNaoContaRecusadas() {
        var rl = new Solution.SlidingWindowLog(1, 100, () -> agora[0]);
        assertTrue(rl.allow("a"));
        for (int t = 1; t < 100; t++) {
            agora[0] = t;
            assertFalse(rl.allow("a"));
        }
        agora[0] = 100;
        assertTrue(rl.allow("a"));
    }

    @Test void logEvitaRajadaNaFronteiraDeJanelaFixa() {
        // Uma janela fixa de 1 s deixaria passar 4 requisições entre t=999 e t=1000.
        var rl = new Solution.SlidingWindowLog(2, 1_000, () -> agora[0]);
        agora[0] = 998;
        assertTrue(rl.allow("a"));
        agora[0] = 999;
        assertTrue(rl.allow("a"));
        agora[0] = 1_000;
        assertFalse(rl.allow("a"));
        assertFalse(rl.allow("a"));
    }

    @Test void parametrosInvalidos() {
        assertThrows(IllegalArgumentException.class, () -> new Solution.TokenBucket(0, 1, () -> 0));
        assertThrows(IllegalArgumentException.class, () -> new Solution.TokenBucket(1, 0, () -> 0));
        assertThrows(IllegalArgumentException.class, () -> new Solution.SlidingWindowLog(0, 10, () -> 0));
        assertThrows(IllegalArgumentException.class, () -> new Solution.SlidingWindowLog(1, 0, () -> 0));
    }

    @Test void muitasChamadas() {
        assertTimeout(Duration.ofSeconds(3), () -> {
            var rl = new Solution.SlidingWindowLog(100, 1_000, () -> agora[0]);
            int aceitas = 0;
            for (int i = 0; i < 300_000; i++) {
                agora[0] = i / 10; // 10 chamadas por ms
                if (rl.allow("a")) aceitas++;
            }
            assertEquals(3_000, aceitas); // 100 por segundo durante 30 s
        });
    }
}
